/**
 * Molecular Viewer Helper
 * Usage: createMolViewer("viewerId", "https://path/to/file.xyz", options)
 * 
 * Supported formats: xyz, poscar, vasp, cif, pdb, sdf, mol2
 * 
 * Options:
 *   height: viewer height (default: "500px")
 *   background: background color (default: "white")
 *   style: "ball-stick" | "stick" | "sphere" | "line" (default: "ball-stick")
 *   showBox: show unit cell box (default: true)
 *   showControls: show view control buttons (default: true)
 *   format: force format (auto-detected from extension if not specified)
 *   caption: text to display at top-left corner of canvas
 *   showHbonds: show hydrogen bonds (default: false)
 *   hbondCutoff: H-bond distance cutoff in Angstroms (default: 3.5)
 *   extendX: extend structure periodically in X (a) direction, e.g., 0.3 extends 0.3 cell on each side (default: 0)
 *   extendY: extend structure periodically in Y (b) direction, e.g., 0.3 extends 0.3 cell on each side (default: 0)
 *   extendZ: extend structure periodically in Z (c) direction, e.g., 0.3 extends 0.3 cell on each side (default: 0)
 *   fadeExtended: show extended atoms with reduced opacity (default: false)
 *   zoom: zoom level multiplier (default: 1.0, larger = zoom out)
 *   showBorder: show border around canvas (default: true)
 *   view: initial view direction: "c", "c*", "b", "b*", "a", "a*" (default: default 3Dmol view)
 *   showSmallCages: initially show detected 5^12 hydrate cages (default: false)
 *   showLargeCages: initially show detected 5^12 6^4 hydrate cages (default: false)
 *   smallCageColor: small cage tile color (default: "#4da6ff")
 *   largeCageColor: large cage tile color (default: "#ff9f43")
 *   cageOpacity: cage tile opacity from 0 to 1 (default: 0.5)
 *   cageStyle: "both" | "lines" | "tiles" (default: "both")
 */

// Draw hydrogen bonds between atoms, excluding deleted atoms
// Returns array of shape references for later removal
function drawHydrogenBonds(viewer, hbondCutoff, deletedSerials, existingHbondShapes) {
    // Remove existing H-bond cylinders only (not the unit cell box)
    if (existingHbondShapes && existingHbondShapes.length > 0) {
        for (const shape of existingHbondShapes) {
            viewer.removeShape(shape);
        }
    }
    
    const hbondShapes = [];
    
    // Get all atoms from ALL models (including periodic images)
    const atoms = viewer.selectedAtoms({});
    
    // Filter out deleted atoms
    const activeAtoms = atoms.filter(a => !deletedSerials.has(a.serial));
    
    // Find O atoms (donors/acceptors) and H atoms
    const oxygens = activeAtoms.filter(a => a.elem === 'O');
    const hydrogens = activeAtoms.filter(a => a.elem === 'H');
    
    // For each H, check if it's bonded to O and close to another O
    for (const h of hydrogens) {
        // Find donor O (covalently bonded to this H, ~1.0 Å)
        let donorO = null;
        let minDonorDist = 1.3; // O-H covalent bond < 1.3 Å
        
        for (const o of oxygens) {
            const dist = Math.sqrt(
                Math.pow(h.x - o.x, 2) + 
                Math.pow(h.y - o.y, 2) + 
                Math.pow(h.z - o.z, 2)
            );
            if (dist < minDonorDist) {
                minDonorDist = dist;
                donorO = o;
            }
        }
        
        if (!donorO) continue;
        
        // Find acceptor O (H-bond distance 1.5-2.5 Å from H, O...O < cutoff)
        for (const acceptorO of oxygens) {
            if (acceptorO === donorO) continue;
            
            // O...O distance
            const ooDistance = Math.sqrt(
                Math.pow(donorO.x - acceptorO.x, 2) + 
                Math.pow(donorO.y - acceptorO.y, 2) + 
                Math.pow(donorO.z - acceptorO.z, 2)
            );
            
            // H...O distance
            const hoDistance = Math.sqrt(
                Math.pow(h.x - acceptorO.x, 2) + 
                Math.pow(h.y - acceptorO.y, 2) + 
                Math.pow(h.z - acceptorO.z, 2)
            );
            
            // H-bond criteria: O...O < cutoff (default 3.2 Å) and H...O between 1.5-2.5 Å
            if (ooDistance < hbondCutoff && hoDistance > 1.4 && hoDistance < 2.5) {
                // Draw dashed line for H-bond
                const shape = viewer.addCylinder({
                    start: {x: h.x, y: h.y, z: h.z},
                    end: {x: acceptorO.x, y: acceptorO.y, z: acceptorO.z},
                    radius: 0.08,
                    color: 'blue',
                    dashed: true,
                    dashLength: 0.25,
                    gapLength: 0.12
                });
                hbondShapes.push(shape);
            }
        }
    }
    
    return hbondShapes;
}

function vectorLength(v) {
    return Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

function fractionalToCartesian(frac, lattice) {
    return {
        x: frac[0] * lattice.a[0] + frac[1] * lattice.b[0] + frac[2] * lattice.c[0],
        y: frac[0] * lattice.a[1] + frac[1] * lattice.b[1] + frac[2] * lattice.c[1],
        z: frac[0] * lattice.a[2] + frac[1] * lattice.b[2] + frac[2] * lattice.c[2]
    };
}

function cartesianToFractional(point, lattice) {
    const a = lattice.a, b = lattice.b, c = lattice.c;
    const det = a[0] * (b[1] * c[2] - b[2] * c[1])
              - a[1] * (b[0] * c[2] - b[2] * c[0])
              + a[2] * (b[0] * c[1] - b[1] * c[0]);
    if (Math.abs(det) < 1e-10) return null;
    return [
        ((b[1] * c[2] - b[2] * c[1]) * point.x
         + (b[2] * c[0] - b[0] * c[2]) * point.y
         + (b[0] * c[1] - b[1] * c[0]) * point.z) / det,
        ((c[1] * a[2] - c[2] * a[1]) * point.x
         + (c[2] * a[0] - c[0] * a[2]) * point.y
         + (c[0] * a[1] - c[1] * a[0]) * point.z) / det,
        ((a[1] * b[2] - a[2] * b[1]) * point.x
         + (a[2] * b[0] - a[0] * b[2]) * point.y
         + (a[0] * b[1] - a[1] * b[0]) * point.z) / det
    ];
}

function wrapFractional(frac) {
    return frac.map(value => value - Math.floor(value));
}

function periodicDelta(from, to, lattice, periodicAxes = [true, true, true]) {
    const delta = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
    const baseShift = delta.map((value, axis) => periodicAxes[axis] ? -Math.round(value) : 0);
    let best = null;
    let bestDistance = Infinity;

    // Searching adjacent images also handles skewed cells where independently
    // wrapping the three fractional coordinates is not always the nearest image.
    for (let ia = periodicAxes[0] ? -1 : 0; ia <= (periodicAxes[0] ? 1 : 0); ia++) {
        for (let ib = periodicAxes[1] ? -1 : 0; ib <= (periodicAxes[1] ? 1 : 0); ib++) {
            for (let ic = periodicAxes[2] ? -1 : 0; ic <= (periodicAxes[2] ? 1 : 0); ic++) {
                const shifted = [
                    delta[0] + baseShift[0] + ia,
                    delta[1] + baseShift[1] + ib,
                    delta[2] + baseShift[2] + ic
                ];
                const cart = fractionalToCartesian(shifted, lattice);
                const distance = Math.sqrt(cart.x * cart.x + cart.y * cart.y + cart.z * cart.z);
                if (distance < bestDistance) {
                    bestDistance = distance;
                    best = {fractional: shifted, cartesian: cart, distance: distance};
                }
            }
        }
    }
    return best;
}

function fastPeriodicDistance(from, to, lattice, periodicAxes = [true, true, true]) {
    const delta = to.map((value, axis) => {
        const difference = value - from[axis];
        return difference - (periodicAxes[axis] ? Math.round(difference) : 0);
    });
    const cart = fractionalToCartesian(delta, lattice);
    return Math.sqrt(cart.x * cart.x + cart.y * cart.y + cart.z * cart.z);
}

function nearestOxygenDistance(center, oxygenFractional, lattice, periodicAxes) {
    let nearest = Infinity;
    for (const oxygen of oxygenFractional) {
        nearest = Math.min(nearest, fastPeriodicDistance(center, oxygen, lattice, periodicAxes));
    }
    return nearest;
}

function refineVoidCenter(start, oxygenFractional, lattice, gridCounts, periodicAxes) {
    let center = start.slice();
    let clearance = nearestOxygenDistance(center, oxygenFractional, lattice, periodicAxes);
    let steps = gridCounts.map(count => 0.5 / count);

    for (let iteration = 0; iteration < 24; iteration++) {
        let improved = false;
        for (let axis = 0; axis < 3; axis++) {
            for (const sign of [-1, 1]) {
                const trial = center.slice();
                trial[axis] += sign * steps[axis];
                const trialClearance = nearestOxygenDistance(trial, oxygenFractional, lattice, periodicAxes);
                if (trialClearance > clearance + 1e-5) {
                    center = trial;
                    clearance = trialClearance;
                    improved = true;
                }
            }
        }
        if (!improved) {
            steps = steps.map(step => step / 2);
            if (Math.max(...steps) < 1e-4) break;
        }
    }
    return {
        fractional: center.map((value, axis) =>
            periodicAxes[axis] ? value - Math.floor(value) : value
        ),
        clearance: clearance
    };
}

function prepareFractionalCoordinates(fractional) {
    const periodicAxes = [true, true, true];
    const adjusted = fractional.map(point => point.slice());
    const ranges = [];

    for (let axis = 0; axis < 3; axis++) {
        const values = fractional.map(point => wrapFractional([point[axis]])[0]).sort((a, b) => a - b);
        let largestGap = -1;
        let gapStart = 0;
        for (let i = 0; i < values.length; i++) {
            const next = i + 1 < values.length ? values[i + 1] : values[0] + 1;
            const gap = next - values[i];
            if (gap > largestGap) {
                largestGap = gap;
                gapStart = values[i];
            }
        }

        // A gap larger than 35% of a cell is treated as a slab vacuum region.
        periodicAxes[axis] = largestGap < 0.35;
        if (!periodicAxes[axis]) {
            const cut = gapStart + largestGap / 2;
            for (const point of adjusted) {
                while (point[axis] > cut) point[axis] -= 1;
                while (point[axis] <= cut - 1) point[axis] += 1;
            }
        }
        const axisValues = adjusted.map(point => point[axis]);
        ranges.push({min: Math.min(...axisValues), max: Math.max(...axisValues)});
    }
    return {fractional: adjusted, periodicAxes: periodicAxes, ranges: ranges};
}

function selectWaterOxygens(atoms, lattice) {
    const oxygens = atoms.filter(atom => atom.elem === 'O');
    const hydrogens = atoms.filter(atom => atom.elem === 'H');
    if (!lattice || hydrogens.length === 0) return oxygens;
    const hydrogenFractional = hydrogens.map(atom => cartesianToFractional(atom, lattice));
    return oxygens.filter(oxygen => {
        const oxygenFractional = cartesianToFractional(oxygen, lattice);
        let bondedHydrogens = 0;
        for (const hydrogen of hydrogenFractional) {
            if (periodicDelta(oxygenFractional, hydrogen, lattice).distance <= 1.3) {
                bondedHydrogens++;
                if (bondedHydrogens >= 2) return true;
            }
        }
        return false;
    });
}

function canonicalCycle(cycle) {
    const variants = [];
    const reversed = cycle.slice().reverse();
    for (const ordered of [cycle, reversed]) {
        for (let i = 0; i < ordered.length; i++) {
            variants.push(ordered.slice(i).concat(ordered.slice(0, i)).join('-'));
        }
    }
    variants.sort();
    return variants[0];
}

function polygonNormal(points) {
    const normal = {x: 0, y: 0, z: 0};
    for (let i = 0; i < points.length; i++) {
        const current = points[i];
        const next = points[(i + 1) % points.length];
        normal.x += (current.y - next.y) * (current.z + next.z);
        normal.y += (current.z - next.z) * (current.x + next.x);
        normal.z += (current.x - next.x) * (current.y + next.y);
    }
    const length = Math.sqrt(normal.x * normal.x + normal.y * normal.y + normal.z * normal.z);
    if (length < 1e-10) return null;
    return {x: normal.x / length, y: normal.y / length, z: normal.z / length};
}

function findCageFaces(vertices, bondCutoff) {
    const adjacency = vertices.map(() => []);
    for (let i = 0; i < vertices.length; i++) {
        for (let j = i + 1; j < vertices.length; j++) {
            const dx = vertices[i].x - vertices[j].x;
            const dy = vertices[i].y - vertices[j].y;
            const dz = vertices[i].z - vertices[j].z;
            if (Math.sqrt(dx * dx + dy * dy + dz * dz) <= bondCutoff) {
                adjacency[i].push(j);
                adjacency[j].push(i);
            }
        }
    }

    const cycles = new Map();
    function visit(start, path) {
        for (const neighbour of adjacency[path[path.length - 1]]) {
            if (neighbour === start && (path.length === 5 || path.length === 6)) {
                cycles.set(canonicalCycle(path), path.slice());
            } else if (path.length < 6 && neighbour >= start && !path.includes(neighbour)) {
                visit(start, path.concat(neighbour));
            }
        }
    }
    for (let start = 0; start < vertices.length; start++) visit(start, [start]);

    const faces = [];
    for (const cycle of cycles.values()) {
        const points = cycle.map(index => vertices[index]);
        const centroid = points.reduce((sum, point) => ({
            x: sum.x + point.x / points.length,
            y: sum.y + point.y / points.length,
            z: sum.z + point.z / points.length
        }), {x: 0, y: 0, z: 0});
        const normal = polygonNormal(points);
        if (!normal) continue;

        let maxPlanarityError = 0;
        let allBelow = true;
        let allAbove = true;
        for (const point of points) {
            const distance = (point.x - centroid.x) * normal.x
                           + (point.y - centroid.y) * normal.y
                           + (point.z - centroid.z) * normal.z;
            maxPlanarityError = Math.max(maxPlanarityError, Math.abs(distance));
        }
        for (const point of vertices) {
            const distance = (point.x - centroid.x) * normal.x
                           + (point.y - centroid.y) * normal.y
                           + (point.z - centroid.z) * normal.z;
            if (distance > 0.35) allBelow = false;
            if (distance < -0.35) allAbove = false;
        }
        if (maxPlanarityError <= 0.35 && (allBelow || allAbove)) faces.push(cycle);
    }
    return faces;
}

